/* @lc app=leetcode id=3747 lang=kotlin */ class Solution { fun p9(k: Int): Long = generateSequence(1L) { it * 9 }.elementAt(k) fun countDistinct(n: Long): Long = n.toString().let { s -> s.length.let { L -> (1 until L).sumOf { len -> p9(len) } + s.indices.fold(true to 0L) { (alive, acc), i -> if (!alive) alive to acc else (s[i] - '0').let { d -> (d != 0) to (acc + (if (d >= 1) (d - 1) * p9(L - 1 - i) else 0L)) } }.let { (alive, acc) -> acc + (if (alive) 1 else 0) } } } }